import { DIALOG_DATA, DialogRef } from '@angular/cdk/dialog';
import {
    Component,
    computed,
    EventEmitter,
    inject,
    OnInit,
    Output,
    resource,
    signal,
} from '@angular/core';
import { FormsModule } from '@angular/forms';
import { disabled, form, FormField } from '@angular/forms/signals';
import {
    addGroup,
    cleanObject,
    PlaceGroup,
    PlaceGroupAdMappings,
    queryDomains,
    queryGroups,
    showGroup,
    updateGroup,
} from '@placeos/ts-client';
import { onSaveHotkey, submitFormDialog } from '../common/forms';
import { subtreeFilter } from '../common/hierarchy';
import { i18n } from '../common/locale.service';
import { DialogEvent } from '../common/types';
import { ChipListComponent } from '../ui/controls/chip-list.component';
import { FormFieldComponent } from '../ui/controls/form-field.component';
import { OptionComponent } from '../ui/controls/option.component';
import { SelectComponent } from '../ui/controls/select.component';
import { ItemSearchFieldComponent } from '../ui/custom-fields/item-search-field.component';
import { FullscreenModalShellComponent } from '../ui/fullscreen-modal-shell.component';
import { SettingsToggleComponent } from '../ui/settings-toggle.component';
import { TranslatePipe } from '../ui/translate.pipe';
import { GroupAdGroupsFieldComponent } from './group-ad-groups-field.component';
import {
    GROUP_PERMISSION_FLAGS,
    hasGroupPermission,
    setGroupPermission,
} from './group-permissions';
import {
    applyGroupFormSchema,
    generateGroupFormModel,
    hasStaffGroupSearch,
} from './groups.utilities';

@Component({
    selector: 'group-form',
    template: `
        <fullscreen-modal-shell
            [heading]="heading"
            [loading]="loading()"
            (save)="submit()"
        >
            <form class="flex flex-col">
                <div class="field">
                    <label
                        for="group-name"
                        [class.error]="
                            form.name().invalid() && form.name().touched()
                        "
                    >
                        {{ 'COMMON.FIELD_NAME' | translate }}<span>*</span>
                    </label>
                    <app-form-field>
                        <input
                            id="group-name"
                            [placeholder]="'COMMON.FIELD_NAME' | translate"
                            [formField]="form.name"
                        />
                        <div error>
                            {{ 'GROUPS.NAME_REQUIRED' | translate }}
                        </div>
                    </app-form-field>
                </div>
                <div class="field">
                    <label for="group-description">{{
                        'COMMON.FIELD_DESCRIPTION' | translate
                    }}</label>
                    <app-form-field>
                        <textarea
                            id="group-description"
                            [placeholder]="
                                'COMMON.FIELD_DESCRIPTION' | translate
                            "
                            [formField]="form.description"
                        ></textarea>
                    </app-form-field>
                </div>
                <div class="fieldset">
                    <div class="field">
                        <label for="group-parent" id="group-parent-label">{{
                            'GROUPS.PARENT_ID' | translate
                        }}</label>
                        <item-search-field
                            id="group-parent"
                            role="group"
                            aria-labelledby="group-parent-label"
                            [placeholder]="'GROUPS.PARENT_SEARCH' | translate"
                            [query_fn]="query_parent_groups()"
                            [exclude]="exclude_parent_group"
                            [ngModel]="parent_group()"
                            [ngModelOptions]="{ standalone: true }"
                            (ngModelChange)="setParentGroup($event)"
                        />
                    </div>
                    <div class="field">
                        <label
                            for="group-authority"
                            id="group-authority-label"
                            >{{ 'GROUPS.AUTHORITY_ID' | translate }}</label
                        >
                        <app-form-field>
                            <app-select
                                [placeholder]="
                                    'GROUPS.AUTHORITY_SELECT' | translate
                                "
                                id="group-authority"
                                aria-labelledby="group-authority-label"
                                [formField]="form.authority_id"
                                (selectionChange)="setParentGroup(null)"
                            >
                                @for (
                                    domain of domain_list();
                                    track domain.id
                                ) {
                                    <app-option [value]="domain.id">
                                        {{ domain.name }}
                                    </app-option>
                                }
                            </app-select>
                        </app-form-field>
                    </div>
                </div>
                <div class="field">
                    <label for="group-subsystems">{{
                        'GROUPS.SUBSYSTEMS' | translate
                    }}</label>
                    <app-form-field class="w-full">
                        <app-chip-list
                            inputId="group-subsystems"
                            aria-label="Subsystem List"
                            [placeholder]="'GROUPS.SUBSYSTEMS_HINT' | translate"
                            [formField]="form.subsystems"
                        />
                    </app-form-field>
                </div>
                <fieldset class="field">
                    <legend class="mb-1 text-[0.8em] font-medium">
                        {{ 'GROUPS.DEFAULT_PERMISSIONS' | translate }}
                    </legend>
                    <p class="mb-2 text-xs opacity-60">
                        {{ 'GROUPS.DEFAULT_PERMISSIONS_HINT' | translate }}
                    </p>
                    <div class="grid grid-cols-2 gap-2 sm:grid-cols-4">
                        @for (
                            permission of permission_flags;
                            track permission.key
                        ) {
                            <settings-toggle
                                [ngModel]="
                                    hasPermission(
                                        formModel().default_permissions,
                                        permission.value
                                    )
                                "
                                [ngModelOptions]="{ standalone: true }"
                                (ngModelChange)="
                                    setDefaultPermission(
                                        permission.value,
                                        $event
                                    )
                                "
                            >
                                {{ permission.label | translate }}
                            </settings-toggle>
                        }
                    </div>
                </fieldset>
                <fieldset class="field mt-4">
                    <legend class="mb-1 text-[0.8em] font-medium">
                        {{ 'GROUPS.AD_GROUPS' | translate }}
                    </legend>
                    <p class="mb-2 text-xs opacity-60">
                        {{ 'GROUPS.AD_GROUPS_HINT' | translate }}
                    </p>
                    <group-ad-groups-field
                        [mappings]="formModel().ad_group_mappings"
                        (mappingsChange)="setAdGroupMappings($event)"
                        [default_permissions]="formModel().default_permissions"
                        [searchable]="staff_group_search.value()"
                    />
                </fieldset>
            </form>
        </fullscreen-modal-shell>
    `,
    styles: [``],
    imports: [
        OptionComponent,
        SelectComponent,
        FormFieldComponent,
        ChipListComponent,
        FormsModule,
        ItemSearchFieldComponent,
        TranslatePipe,
        FormField,
        FullscreenModalShellComponent,
        GroupAdGroupsFieldComponent,
        SettingsToggleComponent,
    ],
})
export class GroupFormComponent implements OnInit {
    private _dialog_ref =
        inject<DialogRef<unknown, GroupFormComponent>>(DialogRef);
    private _data = inject<{ item: PlaceGroup }>(DIALOG_DATA);
    private readonly _name = 'GROUPS';

    @Output() public event = new EventEmitter<DialogEvent>();

    public readonly formModel = signal(generateGroupFormModel(this._data.item));
    public readonly form = form(this.formModel, (path) => {
        applyGroupFormSchema(path);
        // Domain is fixed once the group exists, matching the user form
        disabled(path.authority_id, () => !!this._data.item.id);
    });
    public readonly loading = signal<string | null>(null);
    public heading = i18n(
        `${this._name}.${this._data.item.id ? 'EDIT' : 'NEW'}`,
    );
    private readonly _domain_list = resource({
        loader: async () => (await queryDomains({ limit: 1000 })).data,
    });
    public readonly domain_list = computed(
        () => this._domain_list.value() || [],
    );
    public readonly parent_group = signal<PlaceGroup | null>(null);
    public readonly permission_flags = GROUP_PERMISSION_FLAGS;
    public readonly hasPermission = hasGroupPermission;
    /** Whether AD groups can be found with the staff API */
    public readonly staff_group_search = resource({
        params: () => this.formModel().authority_id,
        loader: ({ params }) => hasStaffGroupSearch(params),
    });
    private readonly _excludeSubtree = subtreeFilter((id) => showGroup(id));
    private readonly _authority_id = computed(
        () => this.formModel().authority_id,
    );
    /**
     * Lists groups in the selected authority, as a parent must be in the same
     * authority. Hides this group's descendants, so the parent can't create a
     * cycle. A new function per authority makes the search field query again.
     */
    public readonly query_parent_groups = computed(() => {
        const authority_id = this._authority_id();
        return (q: string) =>
            queryGroups({ q, limit: 20 }).then(({ data }) =>
                this._excludeSubtree(
                    data.filter((group) => group.authority_id === authority_id),
                    this._data.item.id,
                ),
            );
    });
    /** A group can't be its own parent */
    public readonly exclude_parent_group = (group: PlaceGroup, __: string) =>
        group.id === this._data.item.id;

    constructor() {
        onSaveHotkey(() => this.submit());
    }

    public ngOnInit(): void {
        this.loadParentGroup();
    }

    public setParentGroup(group: PlaceGroup | null) {
        this.parent_group.set(group);
        this.formModel.update((value) => ({
            ...value,
            parent_id: group?.id || '',
        }));
        if (!group?.subsystems?.length) return;
        this.formModel.update((value) => ({
            ...value,
            subsystems: Array.from(
                new Set([...(value.subsystems || []), ...group.subsystems]),
            ),
        }));
    }

    public setDefaultPermission(permission: number, enabled: boolean) {
        this.formModel.update((value) => ({
            ...value,
            default_permissions: setGroupPermission(
                value.default_permissions,
                permission,
                enabled,
            ),
        }));
    }

    public setAdGroupMappings(ad_group_mappings: PlaceGroupAdMappings) {
        this.formModel.update((value) => ({ ...value, ad_group_mappings }));
    }

    public async submit(): Promise<void> {
        await submitFormDialog(
            this.form,
            {
                loading: this.loading,
                event: this.event,
                close: () => this._dialog_ref.close(),
            },
            `${this._name}.`,
            () => {
                const form_value = this.formModel();
                const form_item = cleanObject(
                    {
                        ...this._data.item,
                        ...form_value,
                        subsystems: form_value.subsystems || [],
                    },
                    ['', undefined],
                ) as unknown as PlaceGroup;
                return form_item.id
                    ? updateGroup(form_item.id, form_item)
                    : addGroup(form_item);
            },
        );
    }

    private async loadParentGroup() {
        const parent_id = this.formModel().parent_id;
        if (!parent_id) return;
        const parent = await showGroup(parent_id).catch(() => null);
        this.parent_group.set(parent);
    }
}
